def _rle(s):
    if s is None:
        return []
    if isinstance(s, (bytes, bytearray)):
        try:
            s = bytes(s).decode()
        except Exception:
            s = str(s)
    if not isinstance(s, str):
        try:
            s = "".join(list(s))
        except Exception:
            return []
    if s == "":
        return []
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

def solve(s):
    # batch support: list/tuple of strings -> list of results (genuine single-case unchanged)
    if isinstance(s, (list, tuple)):
        # distinguish single list-of-chars? spec says str, so treat list as batch
        # but if it looks like a single sequence of single-char strings, handle as single
        try:
            # if all elements are single-char strings, could be single input as list; handle as single
            if len(s) > 0 and all(isinstance(x, str) and len(x) == 1 for x in s):
                return _rle("".join(s))
        except Exception:
            pass
        return [_rle(x) for x in s]
    return _rle(s)

