def solve(nums):
    nums = list(nums)
    n = len(nums)
    if n <= 1:
        return nums
    i = n - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1
    if i < 0:
        return sorted(nums)
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    nums[i], nums[j] = nums[j], nums[i]
    nums[i+1:] = reversed(nums[i+1:])
    return nums

