def solve(nums):
    if not nums:
        return 0
    n = len(nums)
    # patience sorting O(n log n) for length of LIS (strict)
    tails = []
    for x in nums:
        # find smallest tail >= x (we want strict, so use bisect_left on x)
        import bisect
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
        # for strict, equal elements should map to new slot? 
        # Actually for strict LIS, we want bisect_left so equal replaces same-tail (length unchanged)
    return len(tails)

def solve(a, b):
    n, m = len(a), len(b)
    if n == 0:
        return m
    if m == 0:
        return n
    # use 1D DP
    prev = list(range(m+1))
    for i in range(1, n+1):
        cur = [i] + [0]*m
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
                cur[j] = prev[j-1]
            else:
                cur[j] = 1 + min(prev[j], cur[j-1], prev[j-1])
        prev = cur
    return prev[m]

